type Pi = any;
type RuntimeState = {
  initialized: boolean; cwd: string; agents?: AgentManager; policy?: Policy; mcp?: MCPManager;
  daemon?: DaemonRpcClient; daemonStatus: "configured" | "unavailable";
};
const runtimeByPi = new WeakMap<object, RuntimeState>();
const unavailable = (message: string) => new Proxy({}, { get: () => async () => { throw new Error(message); } }) as any;

export interface SwarmRuntimeOptions {
  cwd?: string; closed?: boolean; allowedTools?: string[]; allowedSkills?: string[];
  allowMutation?: boolean; allowNetwork?: boolean;
  /** Explicit configuration takes precedence over the environment. */
  daemonSocket?: string; daemonToken?: string; daemonTimeoutMs?: number;
}

function daemonConfig(options: SwarmRuntimeOptions): DaemonRpcOptions | undefined {
  const socketPath = options.daemonSocket ?? process.env.PI_SWARM_DAEMON_SOCKET;
  const token = options.daemonToken ?? process.env.PI_SWARM_DAEMON_TOKEN;
  return socketPath && token ? { socketPath, token, timeoutMs: options.daemonTimeoutMs } : undefined;
}

/** Single production integration boundary for the Pi-Swarm extensions. */
export function registerSwarmRuntime(pi: Pi, options: SwarmRuntimeOptions = {}): RuntimeState {
  const cwd = resolve(options.cwd ?? pi.getCwd?.() ?? process.cwd());
  const existing = runtimeByPi.get(pi as object);
  if (existing?.initialized && existing.cwd === cwd) return existing;
  const config = daemonConfig(options);
  const state: RuntimeState = { initialized: true, cwd, daemonStatus: config ? "configured" : "unavailable" };
  runtimeByPi.set(pi as object, state);

  registerSwarmPrompt(pi);
  state.policy = new Policy({ workspace: cwd, allowedTools: options.allowedTools, allowMutation: options.allowMutation, allowNetwork: options.allowNetwork });

  // Registration is inert: no socket is opened while the extension is loading.
  // Each RPC is connected on session_start or on the eventual tool/command call.
  const taskControl: ControlTaskInterface = config ? (state.daemon = new DaemonRpcClient(config), createDaemonControlTask(state.daemon)) : unavailable("Pi-Swarm daemon unavailable: configure PI_SWARM_DAEMON_SOCKET and PI_SWARM_DAEMON_TOKEN");
  const goalLoopControl: GoalLoopControlPlane = config ? createDaemonGoalLoop(state.daemon!) : unavailable("Pi-Swarm daemon unavailable: configure PI_SWARM_DAEMON_SOCKET and PI_SWARM_DAEMON_TOKEN");
  registerGoalLoop(pi, goalLoopControl);
  registerControlTaskTools(pi, taskControl);
  pi.registerTool?.({ name: "daemon_status", label: "daemon status", description: "Show whether the production Pi-Swarm daemon is configured.", parameters: { type: "object", properties: {} }, execute: async () => ({ content: [{ type: "text", text: JSON.stringify({ status: state.daemonStatus, configured: Boolean(config) }) }], details: { status: state.daemonStatus } }) });

  state.agents = registerAgents(pi, new AgentManager({ cwd, concurrency: 4, runner: createPiRunner(pi) }));
  pi.on?.("session_shutdown", () => { state.mcp?.close(); state.daemon?.close(); });
  const manifests = pi.mcpManifests ?? [];
  if (Array.isArray(manifests)) state.mcp = new MCPManager(manifests, { closed: options.closed ?? true, registerTool: tool => pi.registerTool(tool) });
  pi.registerCommand?.("swarm-runtime", { description: "Inspect integrated Pi-Swarm runtime", handler: async (_args: string, ctx: any) => ctx.ui?.notify?.(
    \\`Pi-Swarm runtime active at \\${cwd}; daemon=\\${state.daemonStatus}; mcp=\\${manifests.length}\\`, "info") });
  return state;
}

export default function swarmRuntimeExtension(pi: Pi) { return registerSwarmRuntime(pi); }
